CREATE OR REPLACE FUNCTION public.shop_admin_approve_order(p_order_id uuid, p_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_order public.shop_orders%rowtype;
begin
  if not public.shop_is_admin() then
    raise exception 'دسترسی مدیر لازم است';
  end if;

  select * into v_order
  from public.shop_orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'سفارش پیدا نشد';
  end if;

  if v_order.tracking_code is null
     or v_order.tracking_code <> upper(trim(coalesce(p_code, ''))) then
    raise exception 'کد یکتای سفارش درست نیست';
  end if;

  if v_order.status = 'approved' then
    raise exception 'این سفارش قبلاً توسط مدیر تأیید شده است';
  end if;

  if v_order.status <> 'shipping' then
    raise exception 'فقط سفارش در انتظار تأیید مدیر قابل تأیید است';
  end if;

  if not v_order.inventory_deducted then
    raise exception 'ثبت کسر موجودی سفارش معتبر نیست';
  end if;

  update public.shop_orders
     set status = 'approved',
         admin_approved_at = now(),
         admin_approved_by = auth.uid()
   where id = p_order_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.shop_admin_archive_order_report(p_order_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not public.shop_is_admin() then
    raise exception 'دسترسی مدیر لازم است';
  end if;

  if p_order_id is null then
    raise exception 'شناسه گزارش معتبر نیست';
  end if;

  update public.shop_orders
     set report_archived_at = now(),
         report_archived_by = auth.uid()
   where id = p_order_id
     and report_archived_at is null;

  if not found then
    raise exception 'گزارش پیدا نشد یا قبلاً حذف شده است';
  end if;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.shop_admin_create_activation_code(p_expires_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_code text;
  v_id uuid;
  v_expires timestamptz;
begin
  if not public.shop_is_admin() then raise exception 'دسترسی مدیر لازم است'; end if;
  if p_expires_days is null or p_expires_days not between 1 and 365 then
    raise exception 'مدت اعتبار کد باید بین ۱ تا ۳۶۵ روز باشد';
  end if;
  v_code := 'BYR-' || upper(encode(extensions.gen_random_bytes(16), 'hex'));
  v_expires := now() + make_interval(days => p_expires_days);
  insert into public.shop_activation_codes(code_hash, code_hint, expires_at, created_by)
  values (encode(extensions.digest(v_code, 'sha256'), 'hex'), right(v_code, 4), v_expires, auth.uid())
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'code', v_code, 'expires_at', v_expires);
end;
$function$

CREATE OR REPLACE FUNCTION public.shop_admin_delete_order(p_order_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.shop_orders%rowtype;
  v_product_id bigint;
  v_qty integer;
begin
  if not public.shop_is_admin() then
    raise exception 'دسترسی مدیر لازم است';
  end if;
  if p_order_id is null then
    raise exception 'شناسه سفارش معتبر نیست';
  end if;

  select * into v_order
  from public.shop_orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'سفارش پیدا نشد';
  end if;

  -- Only restore stock for orders that were still awaiting manager approval.
  if v_order.status = 'shipping' and v_order.inventory_deducted then
    for v_product_id, v_qty in
      select (value->>'product_id')::bigint,
             sum((value->>'qty')::integer)::integer
      from jsonb_array_elements(v_order.items)
      where value ? 'product_id'
      group by (value->>'product_id')::bigint
      order by (value->>'product_id')::bigint
    loop
      update public.shop_products
      set stock_qty = case when stock_qty is null then null else stock_qty + v_qty end,
          in_stock = true
      where id = v_product_id;
    end loop;
  end if;

  delete from public.shop_orders where id = p_order_id;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.shop_admin_deliver(p_order_id uuid, p_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order public.shop_orders%rowtype;
BEGIN
  IF NOT public.shop_is_admin() THEN
    RAISE EXCEPTION 'دسترسی مدیر لازم است';
  END IF;

  SELECT *
    INTO v_order
    FROM public.shop_orders
   WHERE id = p_order_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'سفارش پیدا نشد';
  END IF;

  IF v_order.tracking_code IS NULL
     OR v_order.tracking_code <> upper(btrim(coalesce(p_code, ''))) THEN
    RAISE EXCEPTION 'کد یکتای سفارش درست نیست';
  END IF;

  IF v_order.status = 'done' THEN
    RAISE EXCEPTION 'این سفارش قبلاً تکمیل شده است';
  END IF;

  IF v_order.status <> 'approved' THEN
    RAISE EXCEPTION 'ابتدا باید سفارش توسط مدیر تأیید شود';
  END IF;

  IF NOT v_order.inventory_deducted THEN
    RAISE EXCEPTION 'وضعیت کسر موجودی سفارش معتبر نیست';
  END IF;

  UPDATE public.shop_orders
     SET status = 'done',
         delivered_at = now(),
         delivery_verified = true
   WHERE id = p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.shop_admin_set_order_status(p_order_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order public.shop_orders%rowtype;
  v_product_id bigint;
  v_qty integer;
begin
  if not public.shop_is_admin() then
    raise exception 'دسترسی مدیر لازم است';
  end if;
  if p_status is distinct from 'cancelled' then
    raise exception 'تنها لغو سفارش از این بخش مجاز است';
  end if;

  select * into v_order from public.shop_orders where id = p_order_id for update;
  if not found then raise exception 'سفارش پیدا نشد'; end if;
  if v_order.status in ('done','cancelled') then
    raise exception 'سفارش بسته یا لغو شده و قابل تغییر نیست';
  end if;

  if v_order.inventory_deducted then
    for v_product_id, v_qty in
      select (value->>'product_id')::bigint, sum((value->>'qty')::integer)::integer
        from jsonb_array_elements(v_order.items)
       where value ? 'product_id'
       group by (value->>'product_id')::bigint
       order by (value->>'product_id')::bigint
    loop
      update public.shop_products
         set stock_qty = case when stock_qty is null then null else stock_qty + v_qty end,
             in_stock = true
       where id = v_product_id;
    end loop;
  end if;

  update public.shop_orders
     set status = 'cancelled', inventory_deducted = false
   where id = p_order_id;
end
$function$

CREATE OR REPLACE FUNCTION public.shop_admin_update_order_report(p_order_id uuid, p_customer_name text, p_phone text, p_address text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not public.shop_is_admin() then
    raise exception 'دسترسی مدیر لازم است';
  end if;

  if p_order_id is null
     or char_length(btrim(coalesce(p_customer_name, ''))) < 1
     or char_length(btrim(coalesce(p_customer_name, ''))) > 120
     or char_length(btrim(coalesce(p_phone, ''))) < 5
     or char_length(btrim(coalesce(p_phone, ''))) > 30
     or char_length(btrim(coalesce(p_address, ''))) < 1
     or char_length(btrim(coalesce(p_address, ''))) > 500 then
    raise exception 'اطلاعات گزارش معتبر نیست';
  end if;

  update public.shop_orders
     set customer_name = btrim(p_customer_name),
         phone = btrim(p_phone),
         address = btrim(p_address)
   where id = p_order_id
     and report_archived_at is null;

  if not found then
    raise exception 'گزارش پیدا نشد یا قبلاً حذف شده است';
  end if;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.shop_device_is_activated()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  h jsonb;
  client_info text;
  v_device text;
  v_secret text;
begin
  h := coalesce(nullif(current_setting('request.headers', true), '')::jsonb, '{}'::jsonb);
  client_info := coalesce(h->>'x-client-info','');
  v_device := substring(client_info from 'barqyar-device=([0-9a-fA-F-]{36})');
  v_secret := substring(client_info from 'secret=([0-9a-fA-F]{64})');
  if v_device is null or v_secret is null then return false; end if;
  return exists (
    select 1 from public.shop_activations a
    where a.device_id = v_device::uuid
      and a.secret_hash = encode(extensions.digest(v_secret, 'sha256'), 'hex')
      and a.revoked_at is null
  );
exception when others then
  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.shop_log_price_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if old.price is distinct from new.price then
  insert into public.shop_price_history(product_id,sku,product_name,old_price,new_price,changed_at,changed_by)
  values(new.id,new.sku,new.name,old.price,new.price,now(),coalesce(auth.jwt()->>'email','مدیر'));
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.shop_products_assign_sku()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.sku is null or btrim(new.sku) = '' then
    loop
      new.sku := 'BYK-' || lpad(nextval('public.shop_products_sku_seq')::text, 6, '0');
      exit when not exists (select 1 from public.shop_products p where p.sku = new.sku);
    end loop;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.shop_products_set_code_and_timestamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.sku is null or btrim(new.sku) = '' then
      new.sku := 'BYK-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
    end if;
  else
    new.sku := old.sku;
  end if;

  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.shop_redeem_activation(p_code text, p_device_id uuid, p_device_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_code public.shop_activation_codes%rowtype;
  v_hash text;
begin
  if p_device_id is null or length(coalesce(p_device_secret,'')) < 32 then
    raise exception 'اطلاعات دستگاه معتبر نیست';
  end if;

  if public.shop_check_activation(p_device_id, p_device_secret) then
    return jsonb_build_object('ok', true, 'already_activated', true);
  end if;

  v_hash := encode(extensions.digest(upper(btrim(coalesce(p_code,''))), 'sha256'), 'hex');
  select * into v_code
  from public.shop_activation_codes
  where code_hash = v_hash
  for update;

  if not found or v_code.redeemed_at is not null or v_code.revoked_at is not null or v_code.expires_at <= now() then
    raise exception 'کد فعال‌سازی نامعتبر، منقضی یا قبلاً استفاده شده است';
  end if;

  if exists (select 1 from public.shop_activations where device_id = p_device_id) then
    raise exception 'این دستگاه قبلاً فعال‌سازی شده یا دسترسی آن لغو شده است';
  end if;

  insert into public.shop_activations(device_id, secret_hash, activation_code_id)
  values (p_device_id, encode(extensions.digest(p_device_secret, 'sha256'), 'hex'), v_code.id);

  update public.shop_activation_codes
     set redeemed_at = now(), redeemed_device_id = p_device_id
   where id = v_code.id;

  return jsonb_build_object('ok', true, 'already_activated', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.shop_validate_order_items()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_item jsonb;
  v_product public.shop_products%rowtype;
  v_product_id bigint;
  v_qty integer;
  v_total numeric := 0;
  v_items jsonb := '[]'::jsonb;
begin
  if jsonb_typeof(new.items) <> 'array' or jsonb_array_length(new.items) < 1 then
    raise exception 'سبد خرید خالی است';
  end if;

  for v_item in select value from jsonb_array_elements(new.items)
  loop
    if not (v_item ? 'product_id') then raise exception 'شناسه کالا در سفارش وجود ندارد'; end if;
    v_product_id := (v_item->>'product_id')::bigint;
    v_qty := (v_item->>'qty')::integer;
    if v_qty is null or v_qty < 1 or v_qty > 10000 then raise exception 'تعداد کالا نامعتبر است'; end if;
  end loop;

  -- Lock and validate every product in a stable order to avoid overselling.
  for v_product_id, v_qty in
    select (value->>'product_id')::bigint, sum((value->>'qty')::integer)::integer
      from jsonb_array_elements(new.items)
     group by (value->>'product_id')::bigint
     order by (value->>'product_id')::bigint
  loop
    select * into v_product from public.shop_products where id = v_product_id for update;
    if not found or not v_product.in_stock then raise exception 'یکی از کالاها موجود نیست'; end if;
    if v_product.stock_qty is not null and v_product.stock_qty < v_qty then
      raise exception 'موجودی کالای % کافی نیست. موجودی: %', v_product.name, v_product.stock_qty;
    end if;
  end loop;

  for v_item in select value from jsonb_array_elements(new.items)
  loop
    v_product_id := (v_item->>'product_id')::bigint;
    v_qty := (v_item->>'qty')::integer;
    select * into v_product from public.shop_products where id = v_product_id;
    if v_item ? 'price' and (v_item->>'price')::numeric <> v_product.price then
      raise exception 'قیمت کالای % تغییر کرده است؛ صفحه فروشگاه را تازه کنید و دوباره سفارش دهید.', v_product.name;
    end if;
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'product_id', v_product.id,'name', v_product.name,'unit', v_product.unit,
      'qty', v_qty,'price', v_product.price,'line_total', v_product.price * v_qty
    ));
    v_total := v_total + (v_product.price * v_qty);
  end loop;

  -- Sending an order now reserves/deducts stock; no manager approval/preparation stages.
  for v_product_id, v_qty in
    select (value->>'product_id')::bigint, sum((value->>'qty')::integer)::integer
      from jsonb_array_elements(new.items)
     group by (value->>'product_id')::bigint
     order by (value->>'product_id')::bigint
  loop
    update public.shop_products
       set stock_qty = case when stock_qty is null then null else stock_qty - v_qty end,
           in_stock = case when stock_qty is null then in_stock else (stock_qty - v_qty) > 0 end
     where id = v_product_id;
  end loop;

  new.items := v_items;
  new.total := v_total;
  new.status := 'shipping';
  new.inventory_deducted := true;
  new.payment_status := 'unpaid';
  new.shipping_fee := 0;
  return new;
end
$function$
